//! The day a directory's ids count time from.
//!
//! Each directory of documents named by [ids] records its own epoch in
//! [`EPOCH_FILE`], written when the directory gets its first document, so the
//! time component of a new project's ids starts at zero.
//! Five base-32 characters of five-second buckets cover about 5.3 years from
//! the epoch.
//!
//! The file is a preamble line naming the tool that wrote it, and a
//! `YYYY-MM-DD` line:
//!
//! ```text
//! DO NOT EDIT THIS FILE! IT IS AUTO-GENERATED BY JP-TICKET
//! 2026-08-10
//! ```
//!
//! [ids]: crate::id

use std::{error, fmt, str::FromStr};

use chrono::{DateTime, NaiveDate, NaiveTime};

/// The epoch file, inside the directory whose ids count from it.
pub const EPOCH_FILE: &str = ".epoch";

/// How the date line is written.
const DATE_FORMAT: &str = "%Y-%m-%d";

/// The start of a UTC day that a directory's ids count time from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Epoch(NaiveDate);

impl Epoch {
    /// The epoch starting at midnight UTC on the day `unix_seconds` falls in.
    ///
    /// Rounding down to the day means two checkouts that each file a first
    /// document on the same day write identical files.
    /// Returns `None` for a timestamp past what a date can hold.
    #[must_use]
    pub fn day_of(unix_seconds: u64) -> Option<Self> {
        let seconds = i64::try_from(unix_seconds).ok()?;

        DateTime::from_timestamp(seconds, 0).map(|time| Self(time.date_naive()))
    }

    /// Seconds from the unix epoch to the start of this day.
    ///
    /// A day before 1970 reads as `0`.
    #[must_use]
    pub fn unix_seconds(self) -> u64 {
        let seconds = self.0.and_time(NaiveTime::MIN).and_utc().timestamp();

        u64::try_from(seconds).unwrap_or_default()
    }

    /// The contents of the epoch file holding this epoch, its preamble naming
    /// `writer` as the tool that wrote it: `JP-TICKET`.
    #[must_use]
    pub fn render(self, writer: &str) -> String {
        format!("DO NOT EDIT THIS FILE! IT IS AUTO-GENERATED BY {writer}\n{self}\n")
    }
}

impl fmt::Display for Epoch {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.format(DATE_FORMAT).fmt(f)
    }
}

impl FromStr for Epoch {
    type Err = EpochError;

    /// Read an epoch file: the last non-blank line is the `YYYY-MM-DD` date.
    ///
    /// Everything above it is ignored, so the preamble's wording can change
    /// without breaking files written under the old one.
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let line = s
            .lines()
            .map(str::trim)
            .rfind(|line| !line.is_empty())
            .ok_or(EpochError::Empty)?;

        NaiveDate::parse_from_str(line, DATE_FORMAT)
            .map(Self)
            .map_err(|_| EpochError::NotADate(line.to_owned()))
    }
}

/// An epoch file that doesn't hold an epoch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EpochError {
    /// The file has no date line.
    Empty,

    /// The date line isn't a `YYYY-MM-DD` date.
    NotADate(String),
}

impl fmt::Display for EpochError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Empty => f.write_str("The epoch file holds no date (try 2026-08-10)."),
            Self::NotADate(value) => {
                write!(f, "`{value}` is not an epoch date (try 2026-08-10).")
            }
        }
    }
}

impl error::Error for EpochError {}

